import pytest

from bedrock_protocol import v975, v1001, v2168

# generated by gophertunnel e76ee66:
# &packet.ServerPresenceInfo{PresenceInfo: protocol.Option(protocol.PresenceInfo{ExperienceName: "Demo",
# WorldName: "World"})}
V975 = bytes.fromhex("010444656d6f05576f726c64")

# generated by gophertunnel 6353c49:
# &packet.ServerPresenceInfo{PresenceInfo: protocol.Option(protocol.PresenceInfo{ExperienceName:
# protocol.Option("Demo"), WorldName: protocol.Option("World"), RichPresenceID: "rp1"})}
V1001 = bytes.fromhex("01010444656d6f0105576f726c6403727031")

# generated by gophertunnel 6353c49:
# &packet.ServerPresenceInfo{PresenceInfo: protocol.Option(protocol.PresenceInfo{RichPresenceID: "rp1"})}
V1001_NO_NAMES = bytes.fromhex("01000003727031")

# generated by gophertunnel 6353c49:
# &packet.ServerPresenceInfo{}
ABSENT = bytes.fromhex("00")

GOLDENS = [
    pytest.param(
        v975.ServerPresenceInfoPacket(
            presence_configuration=v975.PresenceConfiguration(experience_name="Demo", world_name="World")
        ),
        V975,
        id="v975",
    ),
    pytest.param(
        v1001.ServerPresenceInfoPacket(
            presence_configuration=v1001.PresenceConfiguration(
                experience_name="Demo", world_name="World", rich_presence_id="rp1"
            )
        ),
        V1001,
        id="v1001",
    ),
    pytest.param(
        v1001.ServerPresenceInfoPacket(
            presence_configuration=v1001.PresenceConfiguration(
                experience_name=None, world_name=None, rich_presence_id="rp1"
            )
        ),
        V1001_NO_NAMES,
        id="v1001-no-names",
    ),
    pytest.param(v975.ServerPresenceInfoPacket(presence_configuration=None), ABSENT, id="v975-absent"),
    pytest.param(v1001.ServerPresenceInfoPacket(presence_configuration=None), ABSENT, id="v1001-absent"),
    pytest.param(v2168.ServerPresenceInfoPacket(presence_configuration=None), ABSENT, id="v2168-absent"),
]


@pytest.mark.parametrize("version", [v975, v1001, v2168], ids=lambda version: version.__name__.rpartition(".")[2])
def test_server_presence_info_is_packet_347(version):
    assert version.PACKETS[347] is version.ServerPresenceInfoPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_server_presence_info_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_server_presence_info_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet


def test_v2168_round_trips_through_its_own_serializer():
    packet = v2168.ServerPresenceInfoPacket(presence_configuration=v2168.PresenceConfiguration(rich_presence_id="rp1"))
    assert len(bytes(packet)) == 6
    assert v2168.ServerPresenceInfoPacket.from_bytes(bytes(packet)) == packet


def test_the_v2168_form_encodes_an_absent_rich_presence_id_as_a_bare_flag():
    present = v2168.ServerPresenceInfoPacket(presence_configuration=v2168.PresenceConfiguration(rich_presence_id="rp1"))
    absent = v2168.ServerPresenceInfoPacket(presence_configuration=v2168.PresenceConfiguration(rich_presence_id=None))
    assert len(bytes(absent)) == len(bytes(present)) - 4
    assert v2168.ServerPresenceInfoPacket.from_bytes(bytes(absent)) == absent


def test_a_v975_body_does_not_decode_as_a_v1001_one():
    with pytest.raises(ValueError, match="at byte"):
        v1001.ServerPresenceInfoPacket.from_bytes(V975)


def test_a_v1001_body_does_not_decode_as_a_v2168_one():
    with pytest.raises(ValueError, match="trailing bytes"):
        v2168.ServerPresenceInfoPacket.from_bytes(V1001)


def test_a_v2168_body_does_not_decode_as_a_v1001_one():
    packet = v2168.ServerPresenceInfoPacket(presence_configuration=v2168.PresenceConfiguration(rich_presence_id="rp1"))
    with pytest.raises(ValueError, match="at byte"):
        v1001.ServerPresenceInfoPacket.from_bytes(bytes(packet))
